import Foundation
import Testing
@testable import MediaEngine

/// Compares what the engine reports with `ffprobe` output committed next to each fixture
/// (`Fixtures/ground-truth/*.json`, regenerated by `scripts/make-fixtures.sh`).
@Suite("ffprobe ground truth")
struct GroundTruthTests {
    private func number(_ value: Any?) -> Double? {
        if let number = value as? Double { return number }
        if let text = value as? String { return Double(text) }
        return nil
    }

    private func frameRate(_ text: String?) -> Double? {
        guard let parts = text?.split(separator: "/"), parts.count == 2,
              let numerator = Double(parts[0]), let denominator = Double(parts[1]), denominator > 0 else { return nil }
        return numerator / denominator
    }

    private func bitDepth(pixelFormat: String?) -> Int? {
        guard let pixelFormat, pixelFormat.hasPrefix("yuv") || pixelFormat.hasPrefix("p0") else { return nil }
        if pixelFormat.contains("p10") || pixelFormat.hasPrefix("p010") { return 10 }
        if pixelFormat.contains("p12") { return 12 }
        return 8
    }

    @Test("every fixture matches ffprobe", arguments: Fixture.names)
    func matches(name: String) async throws {
        let truth = try Fixture.groundTruth(name)
        let info = try await Fixture.probe(name)

        // --- format ---
        let format = try #require(truth["format"] as? [String: Any])
        #expect(abs((info.duration ?? -1) - (number(format["duration"]) ?? -2)) < 0.01, "duration")
        #expect(info.title == (format["tags"] as? [String: String])?["title"], "title")
        #expect(info.container.formatName == format["format_name"] as? String, "format name")

        // --- streams: tracks are the ffprobe streams minus attachments and attached pictures ---
        let streams = try #require(truth["streams"] as? [[String: Any]])
        let attachmentStreams = streams.filter {
            ($0["codec_type"] as? String) == "attachment" || (($0["disposition"] as? [String: Int])?["attached_pic"] ?? 0) == 1
        }
        let trackStreams = streams.filter { stream in !attachmentStreams.contains { ($0["index"] as? Int) == (stream["index"] as? Int) } }
            .filter { ["video", "audio", "subtitle"].contains($0["codec_type"] as? String ?? "") }
        #expect(info.tracks.count == trackStreams.count, "track count")
        #expect(info.attachments.count == attachmentStreams.count, "attachment count")

        for (track, stream) in zip(info.tracks, trackStreams) {
            let label = "\(name) stream \(stream["index"] ?? "?")"
            #expect(track.id == stream["index"] as? Int, "\(label) index")
            #expect(track.kind.rawValue == stream["codec_type"] as? String, "\(label) kind")
            #expect(track.codec.name == stream["codec_name"] as? String, "\(label) codec")
            if let profile = track.codec.profile, let expected = stream["profile"] as? String {
                #expect(profile == expected, "\(label) profile")
            }

            let tags = stream["tags"] as? [String: String] ?? [:]
            #expect(track.title == tags["title"], "\(label) title")
            #expect(track.language == LanguageCodes.language(from: tags["language"]), "\(label) language")

            let disposition = stream["disposition"] as? [String: Int] ?? [:]
            #expect(track.isDefault == ((disposition["default"] ?? 0) == 1), "\(label) default")
            #expect(track.isForced == ((disposition["forced"] ?? 0) == 1), "\(label) forced")

            if let video = track.video {
                #expect(Double(video.width) == number(stream["width"]), "\(label) width")
                #expect(Double(video.height) == number(stream["height"]), "\(label) height")
                if let rate = video.frameRate, let expected = frameRate(stream["avg_frame_rate"] as? String) {
                    #expect(abs(rate - expected) < 0.01, "\(label) frame rate")
                }
                if let depth = video.bitDepth {
                    let expected = number(stream["bits_per_raw_sample"]).map(Int.init) ?? bitDepth(pixelFormat: stream["pix_fmt"] as? String)
                    #expect(depth == expected, "\(label) bit depth")
                }
                for (ours, key) in [(video.colorPrimaries, "color_primaries"), (video.colorTransfer, "color_transfer"), (video.colorMatrix, "color_space")] {
                    let expected = stream[key] as? String
                    #expect(ours == (expected == "unknown" ? nil : expected), "\(label) \(key)")
                }
            }
            if let audio = track.audio {
                #expect(Double(audio.channels) == number(stream["channels"]), "\(label) channels")
                #expect(Double(audio.sampleRate ?? -1) == number(stream["sample_rate"]), "\(label) sample rate")
                if let layout = audio.channelLayout, let expected = stream["channel_layout"] as? String {
                    #expect(layout == expected, "\(label) layout")
                }
            }
        }

        // --- chapters ---
        let chapters = truth["chapters"] as? [[String: Any]] ?? []
        #expect(info.chapters.count == chapters.count, "chapter count")
        for (chapter, expected) in zip(info.chapters, chapters) {
            #expect(chapter.title == (expected["tags"] as? [String: String])?["title"], "chapter title")
            #expect(abs(chapter.start - (number(expected["start_time"]) ?? -1)) < 0.001, "chapter start")
            #expect(abs(chapter.end - (number(expected["end_time"]) ?? -1)) < 0.001, "chapter end")
        }
    }
}
